function placesForZoom(zoomValue) {
    const zoom = Math.max(1, Math.min(8, Number(zoomValue) || 1));
    let maxScaleRank = 2;
    if (zoom >= 1.6) maxScaleRank = 4;
    if (zoom >= 2.8) maxScaleRank = 6;
    if (zoom >= 4.5) maxScaleRank = 8;
    if (zoom >= 6.5) maxScaleRank = 10;

    const rows = [];
    for (let i = 0; i < places.length; i++) {
        const row = places[i];
        const important =
            row.megacity
            || (row.worldcity && row.popMax >= 1000000)
            || (row.adm0cap && row.popMax >= 1500000);
        if (row.scalerank <= maxScaleRank || important)
            rows.push(row);
    }
    return rows;
}
